/* ===================== BÀI 39 · Bàn phím ma trận ===================== */
/* Bài 39 · Bàn phím ma trận (AMTS-EMB-001-M10-L03, MC51-039) — sinh bởi tools/author/mcu8051/l39.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR39=[{"label":"Ví dụ: Kéo hàng 0 xuống 0 rồi đọc cột","code":"; Ví dụ 1: kéo hàng 0 xuống 0 rồi đọc 4 cột\n; Bàn phím 4x4: hàng P1.0…P1.3, cột P1.4…P1.7 (có điện\n; trở kéo lên). Phím nối hàng với cột khi bấm.\n        ORG     0000H\n        MOV     P1,#0FEH                ; hàng 0 = 0; cột ghi 1 để đọc\n        MOV     A,P1                    ; đọc mức chân\n        ANL     A,#0F0H                 ; giữ 4 bit cột\n        MOV     30H,A                   ; F0H = không có phím ở hàng 0\n        SJMP    $\n        END\n","note":"Không giữ phím: 30H = F0H. Đánh dấu Giữ phím, chọn “2” rồi Chạy lại: hàng 0 = 0 kéo cột 1 (P1.5) xuống, 30H = D0H. Chọn “5” (hàng 1): hàng 0 không thấy gì, vẫn F0H.","dev":{"key":true},"fosc":12000000,"speed":"fast"},{"label":"Ví dụ: Quét đủ 4 hàng, ra mã phím","code":"; Ví dụ 2: quét đủ 4 hàng, ra mã phím ở 30H\n; Mã = hàng x 4 + cột (0…15); FFH = không có phím.\n        ORG     0000H\n        MOV     R2,#0FEH                ; mẫu hàng: hàng 0 = 0\n        MOV     R3,#0                   ; mã phím đầu hàng (0, 4, 8, 12)\nROW:    MOV     P1,R2                   ; cột luôn = 1 để đọc được\n        MOV     A,P1\n        ORL     A,#0FH                  ; bỏ 4 bit hàng\n        CJNE    A,#0FFH,FOUND\n        MOV     A,R3\n        ADD     A,#4\n        MOV     R3,A\n        MOV     A,R2\n        RL      A                       ; hàng kế tiếp\n        MOV     R2,A\n        CJNE    R3,#16,ROW\n        MOV     30H,#0FFH               ; quét hết, không có phím\n        SJMP    DONE\nFOUND:  SWAP    A                       ; 4 bit cột xuống thấp\nCOL:    RRC     A                       ; bit cột 0, 1, 2, 3 lần lượt ra CY\n        JNC     GOT\n        INC     R3\n        SJMP    COL\nGOT:    MOV     30H,R3\nDONE:   MOV     P1,#0FFH                ; thả mọi hàng\n        SJMP    $\n        END\n","note":"Không phím: 4 hàng × 14 chu kỳ + 8 = 64 chu kỳ, 30H = FFH. Giữ phím “6”: hàng 1 có cột 2 = 0, SWAP rồi 3 lần RRC → mã 06H sau 42 chu kỳ. Theo dõi R2 (mẫu hàng FEH → FDH …) và R3 (mã đầu hàng 0, 4, 8, 12).","dev":{"key":true},"fosc":12000000,"speed":"fast"},{"label":"Lỗi: Cột ghi 0 nên luôn đọc như có phím","code":"; Ví dụ 3 (lỗi): ghi 0 vào cả các chân cột\n; Chân cổng 8051 chỉ đọc được mức ngoài khi chốt = 1.\n        ORG     0000H\n        MOV     P1,#0EH                 ; hàng 0 = 0 nhưng cột cũng = 0\n        MOV     A,P1\n        ANL     A,#0F0H\n        MOV     30H,A                   ; 00H: như thể bấm cả 4 phím\n        SJMP    $\n        END\n","note":"MOV P1,#0EH ghi 0 vào cả 4 chân cột: chân bị kéo xuống ngay trong chip nên lệnh đọc thấy 0 ở mọi cột, 30H = 00H dù không có phím nào. Sửa: cột phải ghi 1 (P1 = FEH).","dev":{"key":true},"fosc":12000000,"speed":"fast"},{"label":"Ví dụ: Chống dội bằng 3 lần đọc giống nhau","code":"; Ví dụ 4: chống dội - nhận phím khi 3 lần đọc liên\n; tiếp (cách nhau khoảng 10 ms) cho cùng một mã.\n        ORG     0000H\n        ACALL   SCAN                    ; lần đọc đầu\n        MOV     R5,A                    ; R5 = mã lần trước\n        MOV     R6,#1                   ; R6 = số lần giống nhau liên tiếp\n        MOV     R4,#10                  ; đọc thêm tối đa 10 lần\nNEXT:   ACALL   D10MS\n        ACALL   SCAN\n        CJNE    A,05H,DIFF              ; so với R5 (ô 05H của băng 0)\n        INC     R6\n        CJNE    R6,#3,MORE\n        SJMP    DONE                    ; đủ 3 lần giống nhau\nDIFF:   MOV     R5,A                    ; mã đổi: đếm lại từ 1\n        MOV     R6,#1\nMORE:   DJNZ    R4,NEXT\n        MOV     R5,#0FFH                ; không ổn định: bỏ qua\nDONE:   MOV     30H,R5                  ; mã đã lọc\n        SJMP    $\n; ---- quét bàn phím: A = mã phím 0…15 (hàng x 4 + cột) ----\n; ---- hoặc FFH nếu không có phím; dùng R2, R3 ----\nSCAN:   MOV     R2,#0FEH                ; hàng 0 = 0, cột = 1\n        MOV     R3,#0                   ; mã phím đầu hàng\nSROW:   MOV     P1,R2\n        MOV     A,P1\n        ORL     A,#0FH                  ; chỉ giữ 4 bit cột\n        CJNE    A,#0FFH,SFND            ; có cột = 0?\n        MOV     A,R3\n        ADD     A,#4\n        MOV     R3,A\n        MOV     A,R2\n        RL      A                       ; hàng kế tiếp\n        MOV     R2,A\n        CJNE    R3,#16,SROW\n        MOV     A,#0FFH                 ; không có phím\n        SJMP    SEND\nSFND:   SWAP    A                       ; cột về 4 bit thấp\nSCOL:   RRC     A\n        JNC     SGOT                    ; bit = 0: đúng cột\n        INC     R3\n        SJMP    SCOL\nSGOT:   MOV     A,R3\nSEND:   MOV     P1,#0FFH                ; thả mọi hàng\n        RET\nD10MS:  MOV     R0,#20                  ; 1 + 20 x 499 + 2 = 9 983\nDL1:    MOV     R1,#248\n        DJNZ    R1,$\n        DJNZ    R0,DL1\n        RET\n        END\n","note":"Đọc mã mỗi khoảng 10 ms, nhận khi 3 lần liên tiếp giống nhau. Không phím: 20 190 chu kỳ, 30H = FFH. Giữ phím “8”: 30H = 09H sau 20 148 chu kỳ. R6 đếm số lần giống nhau, R4 giới hạn 10 lần đọc thêm.","dev":{"key":true},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Mã phím thành ký tự trên phím","code":"; Ví dụ 5: mã phím thành ký tự in trên phím (ASCII)\n        ORG     0000H\n        ACALL   SCAN                    ; A = 0…15 hoặc FFH\n        MOV     30H,A\n        CJNE    A,#16,CHK               ; CY = 1 nếu A < 16\nCHK:    JC      MAP\n        MOV     31H,#'-'                ; không có phím\n        SJMP    DONE\nMAP:    MOV     DPTR,#KEYTXT\n        MOVC    A,@A+DPTR               ; ký tự theo vị trí phím\n        MOV     31H,A\nDONE:   SJMP    $\n; ---- quét bàn phím: A = mã phím 0…15 (hàng x 4 + cột) ----\n; ---- hoặc FFH nếu không có phím; dùng R2, R3 ----\nSCAN:   MOV     R2,#0FEH                ; hàng 0 = 0, cột = 1\n        MOV     R3,#0                   ; mã phím đầu hàng\nSROW:   MOV     P1,R2\n        MOV     A,P1\n        ORL     A,#0FH                  ; chỉ giữ 4 bit cột\n        CJNE    A,#0FFH,SFND            ; có cột = 0?\n        MOV     A,R3\n        ADD     A,#4\n        MOV     R3,A\n        MOV     A,R2\n        RL      A                       ; hàng kế tiếp\n        MOV     R2,A\n        CJNE    R3,#16,SROW\n        MOV     A,#0FFH                 ; không có phím\n        SJMP    SEND\nSFND:   SWAP    A                       ; cột về 4 bit thấp\nSCOL:   RRC     A\n        JNC     SGOT                    ; bit = 0: đúng cột\n        INC     R3\n        SJMP    SCOL\nSGOT:   MOV     A,R3\nSEND:   MOV     P1,#0FFH                ; thả mọi hàng\n        RET\nKEYTXT: DB      '123A456B789C*0#D'\n        END\n","note":"Chương trình con SCAN trả mã trong A; bảng KEYTXT 16 byte ('123A456B789C*0#D') đổi mã thành ký tự in trên phím. Không phím: 31H = 2DH (“-”). Giữ phím “0” → 31H = 30H; giữ “#” → 23H.","dev":{"key":true},"fosc":12000000,"speed":"fast"}];
