makeEx51(document.getElementById("ex-l39"),"l39",[{"t":"Mã phím từ hàng và byte cột","d":"<p>Bàn phím 4×4 của bo: hàng P1.0…P1.3, cột P1.4…P1.7, mã phím = hàng × 4 + cột (phím “1” = 00H … phím “D” = 0FH). Chương trình quét đã kéo hàng r xuống 0 và đọc P1. Ô <code>30H<\/code> chứa r (0–3), ô <code>31H<\/code> chứa byte đọc được: 4 bit cao là các cột (bit 4 + c = 0 khi phím ở hàng r, cột c đang bấm; nhiều nhất một cột bằng 0), 4 bit thấp là mẫu hàng. Ghi mã phím vào ô <code>32H<\/code>, hoặc <code>FFH<\/code> nếu không cột nào bằng 0. Ô <code>30H<\/code>, <code>31H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 01H<\/code>, <code>31H = BDH<\/code> (1011 1101B: cột 2 = 0) → phím “6”, <code>32H = 06H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     R3,#0                   ; (thiếu: mã đầu hàng = hàng x 4)\n        MOV     A,31H                   ; byte đọc từ P1\n        ORL     A,#0FH\n        CJNE    A,#0FFH,FND\n        MOV     R3,#0FFH                ; không có phím\n        SJMP    DONE\nFND:    SWAP    A\nCOL:    RRC     A\n        JNC     DONE\n        INC     R3\n        SJMP    COL\nDONE:   MOV     32H,R3\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x31":189,"0x32":238}},"expect":{"iram":{"0x30":1,"0x31":189,"0x32":6}}},{"setup":{"iram":{"0x30":0,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":238,"0x32":0}}},{"setup":{"iram":{"0x30":3,"0x31":119,"0x32":238}},"expect":{"iram":{"0x30":3,"0x31":119,"0x32":15}}},{"setup":{"iram":{"0x30":2,"0x31":251,"0x32":238}},"expect":{"iram":{"0x30":2,"0x31":251,"0x32":255}}},{"setup":{"iram":{"0x30":2,"0x31":219,"0x32":238}},"expect":{"iram":{"0x30":2,"0x31":219,"0x32":9}}},{"setup":{"iram":{"0x30":0,"0x31":126,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":126,"0x32":3}}}]},"hints":["Code mẫu tìm đúng cột nhưng luôn bắt đầu đếm từ 0: chỉ đúng với hàng 0.","Mã đầu hàng = 4 × r. Nhân 4 bằng hai lệnh RL A (r ≤ 3 nên không có bit nào bị xoay vòng sai).","Bắt đầu đếm từ mã đầu hàng thay vì từ 0."],"why":"Mã phím ghép từ hai phần: hàng đang quét (4r) và cột đọc được (c). Bộ thử “hàng 2, cột 1” bắt lỗi quên 4r: code mẫu ra 01H thay vì 09H."},{"t":"Nhập số hai chữ số từ bàn phím","d":"<p>Ô <code>30H<\/code> giữ giá trị đang nhập (0–99), ô <code>31H<\/code> là mã phím vừa nhận (0–15, đã lọc dội), ô <code>32H<\/code> là cờ “nhập xong”. Nhãn phím theo mã: <code>1 2 3 A / 4 5 6 B / 7 8 9 C / * 0 # D<\/code>. Bảng <code>KEYVAL<\/code> có sẵn cho giá trị của từng phím (0–9; FEH = “*”; FDH = “#”; FFH = phím chữ). Xử lý một phím:<\/p><ul><li>phím số d: giá trị mới = (hàng đơn vị cũ) × 10 + d, tức chỉ giữ 2 chữ số cuối như máy tính bỏ túi (42 rồi bấm 8 → 28);<\/li><li>“*”: giá trị = 0;<\/li><li>“#”: <code>32H = 01H<\/code>, giá trị giữ nguyên;<\/li><li>phím chữ A–D: không đổi gì.<\/li><\/ul><p>Ô <code>31H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 04H<\/code>, phím “2” (<code>31H = 01H<\/code>) → <code>30H = 2AH<\/code> (42).<\/p>","start":"        ORG     0000H\n        MOV     A,31H                   ; mã phím 0…15\n        MOV     DPTR,#KEYVAL\n        MOVC    A,@A+DPTR               ; 0…9, FEH = '*', FDH = '#', FFH = chữ\n        MOV     R2,A\n        MOV     A,30H\n        MOV     B,#10\n        MUL     AB                      ; (chưa đúng: giá trị cũ x 10)\n        ADD     A,R2\n        MOV     30H,A\n        SJMP    $\n; giá trị của phím theo mã (hàng x 4 + cột)\nKEYVAL: DB      1,2,3,0FFH,4,5,6,0FFH,7,8,9,0FFH,0FEH,0,0FDH,0FFH\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":4,"0x31":1,"0x32":0}},"expect":{"iram":{"0x30":42,"0x31":1,"0x32":0}}},{"setup":{"iram":{"0x30":42,"0x31":9,"0x32":0}},"expect":{"iram":{"0x30":28,"0x31":9,"0x32":0}}},{"setup":{"iram":{"0x30":0,"0x31":13,"0x32":0}},"expect":{"iram":{"0x30":0,"0x31":13,"0x32":0}}},{"setup":{"iram":{"0x30":57,"0x31":12,"0x32":0}},"expect":{"iram":{"0x30":0,"0x31":12,"0x32":0}}},{"setup":{"iram":{"0x30":57,"0x31":14,"0x32":0}},"expect":{"iram":{"0x30":57,"0x31":14,"0x32":1}}},{"setup":{"iram":{"0x30":57,"0x31":3,"0x32":0}},"expect":{"iram":{"0x30":57,"0x31":3,"0x32":0}}},{"setup":{"iram":{"0x30":9,"0x31":10,"0x32":0}},"expect":{"iram":{"0x30":99,"0x31":10,"0x32":0}}}]},"hints":["Tra KEYVAL trước, rồi rẽ nhánh: giá trị &lt; 10 là phím số (CJNE A,#10,$+3 rồi JNC cho trường hợp ≥ 10).","Hàng đơn vị cũ = số dư khi chia 10 (DIV AB để số dư trong B). Nhân 10 bằng MUL AB rồi cộng d.","FEH và FDH phân biệt bằng CJNE; FFH (phím chữ) thì nhảy thẳng tới cuối."],"why":"Bàn phím chỉ cho mã; ý nghĩa của phím (số, xóa, xác nhận) nằm trong bảng và máy trạng thái nhỏ của chương trình. Giữ 2 chữ số cuối tránh tràn byte: code mẫu lấy 42 × 10 = 420 làm tràn A."},{"t":"Một phím hay nhiều phím, ≤ 80 chu kỳ","d":"<p>Một lần quét đọc được 4 bit cột của cả 4 hàng: ô <code>30H<\/code>…<code>33H<\/code> (hàng 0…3), 4 bit thấp là cột (bit c = 0: phím ở cột c đang bấm), 4 bit cao bằng 0. Firmware chỉ chấp nhận <b>đúng một<\/b> phím (giới hạn đã công bố của bàn phím không có điốt). Ghi số phím đang bấm vào ô <code>34H<\/code>; ghi mã phím (hàng × 4 + cột) vào ô <code>35H<\/code> nếu có đúng một phím, ngược lại ghi <code>FFH<\/code>. Ô <code>30H<\/code>…<code>33H<\/code> giữ nguyên. Code mẫu đúng nhưng xét từng bit một (128–148 chu kỳ tùy bộ thử, 40 byte). Hãy viết lại để chạy <b>không quá 80 chu kỳ máy<\/b> (tính cả <code>SJMP $<\/code>) với mọi bộ thử, dài <b>không quá 80 byte<\/b>.<\/p><p>Ví dụ: <code>30H…33H = 0FH 0FH 0DH 0FH<\/code> → <code>34H = 01H<\/code>, <code>35H = 09H<\/code> (phím “8”).<\/p>","start":"        ORG     0000H\n        MOV     R0,#30H                 ; hàng 0\n        MOV     R2,#0                   ; số phím đang bấm\n        MOV     R3,#0FFH                ; mã phím (nếu đúng 1 phím)\n        MOV     R4,#0                   ; mã đang xét\nROWL:   MOV     A,@R0\n        MOV     R5,#4                   ; 4 cột\nCOLL:   RRC     A\n        JC      UP                      ; bit = 1: không bấm\n        INC     R2\n        MOV     R6,A\n        MOV     A,R4\n        MOV     R3,A                    ; nhớ mã phím vừa thấy\n        MOV     A,R6\nUP:     INC     R4\n        DJNZ    R5,COLL\n        INC     R0\n        CJNE    R0,#34H,ROWL\n        MOV     34H,R2\n        CJNE    R2,#1,MANY\n        MOV     35H,R3\n        SJMP    FIN\nMANY:   MOV     35H,#0FFH\nFIN:    SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":15,"0x31":15,"0x32":13,"0x33":15,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":15,"0x31":15,"0x32":13,"0x33":15,"0x34":1,"0x35":9}}},{"setup":{"iram":{"0x30":15,"0x31":15,"0x32":15,"0x33":15,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":15,"0x31":15,"0x32":15,"0x33":15,"0x34":0,"0x35":255}}},{"setup":{"iram":{"0x30":12,"0x31":15,"0x32":15,"0x33":15,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":12,"0x31":15,"0x32":15,"0x33":15,"0x34":2,"0x35":255}}},{"setup":{"iram":{"0x30":12,"0x31":12,"0x32":15,"0x33":15,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":12,"0x31":12,"0x32":15,"0x33":15,"0x34":4,"0x35":255}}},{"setup":{"iram":{"0x30":14,"0x31":12,"0x32":15,"0x33":15,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":14,"0x31":12,"0x32":15,"0x33":15,"0x34":3,"0x35":255}}},{"setup":{"iram":{"0x30":15,"0x31":15,"0x32":15,"0x33":7,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":15,"0x31":15,"0x32":15,"0x33":7,"0x34":1,"0x35":15}}}],"maxCyc":80,"maxBytes":80},"hints":["Code mẫu chạy 16 vòng (4 hàng × 4 cột), mỗi vòng có RRC, JC, DJNZ: phần lớn thời gian là nhảy.","Đổi 16 vòng bit thành 4 lần tra bảng: bảng 16 byte theo giá trị 4 bit cột cho ngay “số phím trong hàng” (số bit 0).","Thêm một bảng cho vị trí cột khi hàng có đúng một phím; đặt nối tiếp bảng đầu thì dùng chung được con trỏ."],"why":"Đổi thời gian lấy bộ nhớ: hai bảng 16 byte trong CODE thay cho 16 vòng xét bit, giảm từ 148 xuống tối đa 73 chu kỳ. Chỉ nhận đúng một phím là cách đơn giản để tránh bóng phím: ba phím ở ba góc hình chữ nhật làm góc thứ tư trông như đang bấm, nên mọi trường hợp từ hai phím trở lên đều bị bỏ qua."}]);

makeQuiz("quiz39","score39",[{"q": "Hàng 2 đang được quét (P1 = FBH) và phím ở cột 3 được bấm. Đọc P1 được giá trị nào?", "o": ["FBH", "7BH", "F7H", "B7H"], "a": 1, "e": "Chốt FBH = 1111 1011B (hàng 2 = 0). Phím cột 3 kéo P1.7 xuống 0: 0111 1011B = 7BH. FBH là khi không có phím; F7H là mẫu của hàng 3."}, {"q": "Vì sao phải ghi 1 vào các chân cột trước khi đọc chúng trên cổng P1 của 8051?", "o": ["Để bật điện trở kéo lên ngoài", "Để chọn chế độ vào cho cổng bằng thanh ghi hướng", "Chốt = 0 kéo chân xuống mạnh trong chip, nên chân luôn đọc 0 bất kể phím", "Vì lệnh MOV A,P1 chỉ đọc được bit bằng 1"], "a": 2, "e": "P1 không có thanh ghi hướng; chân chỉ “làm ngõ vào” được khi chốt = 1 (kéo lên yếu). Ghi 0 thì chân bị kéo xuống trong chip và luôn đọc 0 (ví dụ 3)."}, {"q": "Với mã = hàng × 4 + cột, phím ở hàng 2, cột 1 có mã bao nhiêu?", "o": ["06H", "12H", "09H", "21H"], "a": 2, "e": "2 × 4 + 1 = 9 = 09H (phím “8” trên bàn phím của bo). 06H là hàng 1, cột 2; 21H là ghép hai số thành hex."}, {"q": "Bấm cùng lúc ba phím “1”, “2”, “4” trên ma trận không có điốt. Lần quét có thể báo thêm phím nào?", "o": ["“5”", "“3”", "“7”", "Không phím nào; ma trận chỉ báo đúng phím bấm"], "a": 0, "e": "“1”, “2”, “4” ở ba góc của hình chữ nhật hàng 0–1 × cột 0–1. Dòng đi qua ba phím làm góc thứ tư (hàng 1, cột 1 = “5”) đọc như đang bấm: bóng phím."}, {"q": "Bộ lọc dội đọc mã mỗi 10 ms và nhận khi 3 lần liên tiếp giống nhau. Từ lúc phím hết dội, cần tối thiểu khoảng bao lâu để mã được nhận?", "o": ["10 ms", "30 ms", "3 ms", "Khoảng 20 ms (lần đọc 1 rồi thêm 2 khoảng 10 ms)"], "a": 3, "e": "Lần đọc ổn định đầu tiên đếm 1, cần thêm 2 lần đọc cách nhau 10 ms: khoảng 20 ms (cộng thời gian quét). 30 ms là đếm nhầm 3 khoảng thay vì 2."}]);

